import sys
import json
from typing import Optional

class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def build_list(values):
    head = None
    tail = None
    for x in values:
        node = ListNode(x)
        if head is None:
            head = node
        else:
            tail.next = node
        tail = node
    return head

def to_list(head):
    ans = []
    while head:
        ans.append(head.val)
        head = head.next
    return ans

class Solution:
    def removeElements(self, head: Optional[ListNode], val: int) -> Optional[ListNode]:
        dummy = ListNode(0)
        dummy.next = head
        prev = dummy
        cur = head

        while cur:
            if cur.val == val:
                prev.next = cur.next
            else:
                prev = cur
            cur = cur.next

        return dummy.next

if __name__ == "__main__":
    args = json.loads(sys.stdin.readline())
    head = build_list(args[0])
    val = args[1]
    result = Solution().removeElements(head, val)
    print(json.dumps(to_list(result), separators=(",", ":")))

